const getClosestVowel = (word) => {
  const vowels = "aeiouAEIOU";

  // We iterate from the right side of the word.
  // We start at index word.length - 2 and end at index 1 
  // because vowels at the very beginning or end don't count.
  for (let i = word.length - 2; i >= 1; i--) {
    const char = word[i];

    // Check if current character is a vowel
    if (vowels.includes(char)) {
      const prevChar = word[i - 1];
      const nextChar = word[i + 1];

      // Check if the characters to the left and right are NOT vowels (consonants)
      if (!vowels.includes(prevChar) && !vowels.includes(nextChar)) {
        return char;
      }
    }
  }

  // Return empty string if no such vowel is found
  return "";
};
